/// 🏛️ Validates each actual topology row's document parent without creating owned maps.
fn native_rows(rows:&RowIndex<'_>,c:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{for &index in rows.indices(){let row=rows.row(index)?;if row.integer(1)?!=1{return Err(brep_invalid("invalid BRep document parent"))}row.text(3)?;c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,index,rows.len())?;}Ok(())}
/// 🔎️ Selects an exact topology relationship range through its declared scalar parent.
fn brep_range(rows:&RowIndex<'_>,order:&[usize],owner:i64,c:&mut SqliteSnapshotControl<'_>)->Result<std::ops::Range<usize>,ValueError>{rows.range_by(order,(0,Some(owner)),c,|row|Ok((0,Some(row.integer(1)?))))}
